def norm(txt):
    out = ''
    for ch in str(txt).lower():
        if ch.isalnum():
            out = out + ch
    return out


def clipv(val, low, high):
    if val < low:
        return low
    if val > high:
        return high
    return val


def tofloat(val, dflt):
    if val is None or isinstance(val, bool):
        return dflt
    if isinstance(val, (int, float)):
        return float(val)
    return dflt


def getnum(mapping, key, dflt):
    if not isinstance(mapping, dict):
        return dflt
    return tofloat(mapping.get(key), dflt)


def tkeys(items):
    out = []
    for item in items or []:
        out.append(norm(item))
    return out


