def abfactor(ability, mtype):
    abl = norm(ability)
    mtp = norm(mtype)
    if abl == 'levitate' and mtp == 'ground':
        return 0.0
    if abl == 'flashfire' and mtp == 'fire':
        return 0.0
    if abl in ('waterabsorb', 'stormdrain', 'dryskin') and mtp == 'water':
        return 0.0
    if abl in ('voltabsorb', 'lightningrod', 'motordrive') and mtp == 'electric':
        return 0.0
    if abl == 'sapsipper' and mtp == 'grass':
        return 0.0
    if abl == 'thickfat' and mtp in ('fire', 'ice'):
        return 0.5
    if abl == 'heatproof' and mtp == 'fire':
        return 0.5
    return 1.0


def effmult(chart, atype, dtypes):
    row = chart.get(norm(atype))
    if not row:
        return 1.0
    total = 1.0
    for dtp in dtypes or []:
        total = total * row.get(norm(dtp), 1.0)
    return total


def effon(chart, atype, dtypes, ability):
    return effmult(chart, atype, dtypes) * abfactor(ability, atype)


def boostmul(stage):
    step = int(tofloat(stage, 0.0))
    if step > 6:
        step = 6
    if step < -6:
        step = -6
    if step >= 0:
        return (2.0 + step) / 2.0
    return 2.0 / (2.0 - step)


def rawdmg(power, attack, defense, stab, mult):
    if power <= 0.0 or attack <= 0.0 or defense <= 0.0 or mult <= 0.0:
        return 0.0
    return ((0.44 * power * attack / defense) + 2.0) * stab * mult


def accof(mv):
    val = mv.get('accuracy')
    if val is None or isinstance(val, bool):
        return 1.0
    if isinstance(val, (int, float)):
        num = float(val)
        if num > 1.0:
            num = num / 100.0
        if num <= 0.0 or num > 1.0:
            return 1.0
        return num
    return 1.0


def hitsneeded(frac):
    if frac <= 0.02:
        return 9
    val = int(math.ceil(1.0 / frac))
    return int(clipv(val, 1, 9))


def pctstr(value, cap):
    return str(int(round(100.0 * min(cap, max(0.0, value)))))


def multstr(mult):
    if mult >= 4.0:
        return 'x4 super effective'
    if mult >= 2.0:
        return 'x2 super effective'
    if mult >= 1.0:
        return 'x1 neutral'
    if mult >= 0.5:
        return 'x0.5 resisted'
    if mult > 0.0:
        return 'x0.25 resisted'
    return 'immune'


def basefor(species):
    return basestats().get(norm(species), [85, 90, 90, 90, 90, 85])


def ourhp(mon):
    disp = mon.get('hp_display')
    cur = None
    top = None
    if isinstance(disp, str) and '/' in disp:
        parts = disp.split('/')
        if len(parts) == 2:
            if parts[0].strip().isdigit():
                cur = float(int(parts[0].strip()))
            if parts[1].strip().isdigit():
                top = float(int(parts[1].strip()))
    if top is None or top <= 0.0:
        top = float(basefor(mon.get('species'))[0]) + 100.0
    if cur is None:
        cur = top * getnum(mon, 'hp_fraction', 1.0)
    return [max(1.0, cur), max(1.0, top)]


def unknownweight(rev):
    left = 4 - len(rev)
    if left <= 0:
        return 0.0
    if left == 1:
        return 0.28
    if left == 2:
        return 0.4
    return 0.5


def oppctxof(chart, foe, sandy):
    base = basefor(foe.get('species'))
    types = foe.get('types') or []
    tkl = tkeys(types)
    boosts = foe.get('boosts') if isinstance(foe.get('boosts'), dict) else {}
    rev = []
    for mv in foe.get('revealed_moves') or []:
        if isinstance(mv, dict):
            rev.append(mv)
    frac = getnum(foe, 'hp_fraction', 1.0)
    if frac <= 0.0:
        frac = 0.05
    hpv = float(base[0]) + 100.0
    atk = (float(base[1]) + 52.0) * boostmul(boosts.get('atk', 0))
    dfn = (float(base[2]) + 35.0) * boostmul(boosts.get('def', 0))
    spa = (float(base[3]) + 52.0) * boostmul(boosts.get('spa', 0))
    spd = (float(base[4]) + 35.0) * boostmul(boosts.get('spd', 0))
    spe = (float(base[5]) + 45.0) * boostmul(boosts.get('spe', 0))
    if sandy and 'rock' in tkl:
        spd = spd * 1.5
    status = norm(foe.get('status'))
    omove = 1.0
    if status in ('frz', 'slp'):
        omove = 0.4
    elif status == 'par':
        omove = 0.75
        spe = spe * 0.5
    if status == 'brn':
        atk = atk * 0.5
    return {'chart': chart, 'species': foe.get('species'), 'types': types, 'otkeys': tkl,
            'ability': foe.get('ability'), 'ocur': max(1.0, hpv * frac), 'ofrac': frac,
            'oatk': atk, 'odef': dfn, 'ospa': spa, 'ospd': spd, 'ospe': spe,
            'orev': rev, 'unknown': unknownweight(rev), 'omove': omove, 'ostatus': status}


def ourprofile(mon, sandy, isactive):
    stats = mon.get('stats') or {}
    boosts = {}
    if isactive and isinstance(mon.get('boosts'), dict):
        boosts = mon.get('boosts')
    hpp = ourhp(mon)
    types = mon.get('types') or []
    tkl = tkeys(types)
    status = norm(mon.get('status'))
    prof = {'species': mon.get('species'), 'types': types, 'tkeys': tkl,
            'cur': hpp[0], 'frac': clipv(hpp[0] / hpp[1], 0.0, 1.0),
            'atk': getnum(stats, 'atk', 100.0) * boostmul(boosts.get('atk', 0)),
            'spa': getnum(stats, 'spa', 100.0) * boostmul(boosts.get('spa', 0)),
            'def': getnum(stats, 'def', 100.0) * boostmul(boosts.get('def', 0)),
            'spd': getnum(stats, 'spd', 100.0) * boostmul(boosts.get('spd', 0)),
            'spe': getnum(stats, 'spe', 100.0) * boostmul(boosts.get('spe', 0)),
            'ability': norm(mon.get('ability')), 'status': status, 'boosts': boosts}
    if sandy and 'rock' in tkl:
        prof['spd'] = prof['spd'] * 1.5
    if status == 'brn':
        prof['atk'] = prof['atk'] * 0.5
    if status == 'par':
        prof['spe'] = prof['spe'] * 0.5
    prof['shield'] = 0.5 if (prof['ability'] == 'multiscale' and prof['frac'] >= 0.99) else 1.0
    prof['act'] = 0.75 if status == 'par' else (0.45 if status in ('frz', 'slp') else 1.0)
    return prof


def threaton(ctx, prof):
    chart = ctx['chart']
    dtypes = prof['types']
    abl = prof['ability']
    dfn = prof['def']
    dsp = prof['spd']
    oatk = ctx['oatk']
    ospa = ctx['ospa']
    revbest = 0.0
    revname = 'unrevealed moves'
    for mv in ctx['orev']:
        power = getnum(mv, 'base_power', 0.0)
        if power <= 0.0:
            continue
        mtype = mv.get('type') or ''
        mult = effon(chart, mtype, dtypes, abl)
        stab = 1.5 if norm(mtype) in ctx['otkeys'] else 1.0
        if norm(mv.get('category')) == 'physical':
            hit = rawdmg(power, oatk, dfn, stab, mult)
        else:
            hit = rawdmg(power, ospa, dsp, stab, mult)
        hit = hit * accof(mv)
        if hit > revbest:
            revbest = hit
            revname = str(mv.get('name') or mtype)
    stabbest = 0.0
    for mtype in ctx['types'] or []:
        mult = effon(chart, mtype, dtypes, abl)
        hit = max(rawdmg(85.0, oatk, dfn, 1.5, mult), rawdmg(85.0, ospa, dsp, 1.5, mult))
        if hit > stabbest:
            stabbest = hit
    covbest = 0.0
    covtype = 'none'
    for mtype in alltypes():
        mult = effon(chart, mtype, dtypes, abl)
        if mult <= 1.0:
            continue
        hit = max(rawdmg(85.0, oatk, dfn, 1.0, mult), rawdmg(85.0, ospa, dsp, 1.0, mult))
        if hit > covbest:
            covbest = hit
            covtype = mtype
    neutral = max(rawdmg(75.0, oatk, dfn, 1.0, 1.0), rawdmg(75.0, ospa, dsp, 1.0, 1.0))
    scale = 0.925 * prof['shield'] * ctx['omove'] / prof['cur']
    exp = max(revbest * scale, 0.9 * stabbest * scale, 0.5 * neutral * scale)
    cov = covbest * scale
    risk = exp + ctx['unknown'] * max(0.0, cov - exp)
    sturdy = prof['ability'] == 'sturdy' and prof['frac'] >= 0.99
    if sturdy:
        exp = min(exp, 0.99)
        risk = min(risk, 0.99)
        cov = min(cov, 0.99)
    hidden = 0.0
    if risk > 0.0:
        hidden = clipv((risk - exp) / risk, 0.0, 1.0)
    return {'exp': exp, 'risk': risk, 'cov': cov, 'covtype': covtype, 'revname': revname,
            'hidden': hidden, 'sturdy': sturdy}


def bestoffense(ctx, moves, prof):
    best = 0.0
    bestname = 'no damaging move'
    for mv in moves or []:
        if not isinstance(mv, dict):
            continue
        power = getnum(mv, 'base_power', 0.0)
        if power <= 0.0:
            continue
        mtype = mv.get('type') or ''
        mult = effon(ctx['chart'], mtype, ctx['types'], ctx['ability'])
        stab = 1.5 if norm(mtype) in prof['tkeys'] else 1.0
        atkstat = prof['def'] if norm(mv.get('id')) == 'bodypress' else prof['atk']
        if norm(mv.get('category')) == 'physical':
            hit = rawdmg(power, atkstat, ctx['odef'], stab, mult)
        else:
            hit = rawdmg(power, prof['spa'], ctx['ospd'], stab, mult)
        hit = hit * 0.925 * accof(mv) / ctx['ocur']
        if hit > best:
            best = hit
            bestname = str(mv.get('name') or mtype)
    return [best, bestname]


def matchup(ctx, prof, moves):
    off = bestoffense(ctx, moves, prof)
    thr = threaton(ctx, prof)
    risk = thr['risk']
    exp = thr['exp']
    if prof['ability'] == 'intimidate':
        risk = risk * 0.9
        exp = exp * 0.9
    faster = prof['spe'] > ctx['ospe']
    turnsus = hitsneeded(off[0] * prof['act'])
    turnsthem = hitsneeded(risk)
    margin = clipv(float(turnsthem - turnsus) + (0.4 if faster else -0.4), -5.0, 5.0)
    return {'off': off[0], 'offname': off[1], 'exp': exp, 'risk': risk, 'cov': thr['cov'],
            'covtype': thr['covtype'], 'hidden': thr['hidden'], 'sturdy': thr['sturdy'],
            'revname': thr['revname'], 'faster': faster, 'turnsus': turnsus,
            'turnsthem': turnsthem, 'margin': margin}


def movecand(act, ctx, aprof, amatch):
    mv = act.get('move') or {}
    cid = act.get('id')
    name = str(mv.get('name') or act.get('label') or cid)
    mid = norm(mv.get('id'))
    mtype = str(mv.get('type') or 'typeless')
    cat = norm(mv.get('category'))
    power = getnum(mv, 'base_power', 0.0)
    acc = accof(mv)
    prio = getnum(mv, 'priority', 0.0)
    mult = getnum(mv, 'type_multiplier', -1.0)
    if mult < 0.0:
        mult = effmult(ctx['chart'], mtype, ctx['types'])
    mult = mult * abfactor(ctx['ability'], mtype)
    stab = 1.5 if (mv.get('stab') is True or norm(mtype) in aprof['tkeys']) else 1.0
    atkstat = aprof['def'] if mid == 'bodypress' else aprof['atk']
    if cat == 'physical':
        raw = rawdmg(power, atkstat, ctx['odef'], stab, mult)
    else:
        raw = rawdmg(power, aprof['spa'], ctx['ospd'], stab, mult)
    frac = raw * 0.925 / ctx['ocur']
    foesturdy = norm(ctx['ability']) == 'sturdy' and ctx['ofrac'] >= 0.99
    komin = power > 0.0 and raw * 0.85 >= ctx['ocur'] * 1.12 and not foesturdy
    koavg = power > 0.0 and raw * 0.925 >= ctx['ocur'] and not foesturdy
    wefirst = amatch['faster'] or prio > 0.0
    risk = amatch['risk']
    pfaint = clipv((risk - 0.6) / 0.45, 0.0, 1.0)
    if wefirst and komin:
        pfaint = 0.0
    elif wefirst and koavg:
        pfaint = pfaint * 0.4
    heal = mv.get('heal')
    boosts = mv.get('boosts')
    stt = mv.get('status')
    isheal = power <= 0.0 and (heal is not None or mid in healnames())
    isboost = False
    if power <= 0.0 and isinstance(boosts, dict):
        for key in boosts.keys():
            if getnum(boosts, key, 0.0) > 0.0:
                isboost = True
    isstatus = power <= 0.0 and stt is not None
    turns = hitsneeded(frac * acc)
    if power > 0.0:
        val = 92.0 * min(1.0, frac * acc)
        if komin:
            val = val + 38.0 * acc
        elif koavg:
            val = val + 20.0 * acc
        if komin and prio > 0.0 and not amatch['faster']:
            val = val + 16.0
        rec = mv.get('recoil')
        if isinstance(rec, list) and len(rec) == 2:
            val = val - 24.0 * min(0.5, tofloat(rec[0], 0.0) / max(1.0, tofloat(rec[1], 1.0)))
        if mv.get('drain') is not None:
            val = val + 5.0
        val = val + 7.0 * clipv(float(amatch['turnsthem'] - turns) + (0.4 if amatch['faster'] else -0.4), -3.0, 3.0)
        note = 'about ' + pctstr(frac, 4.0) + ' percent of the target remaining HP'
        if komin:
            note = note + ', a knockout this turn'
        elif koavg:
            note = note + ', likely a knockout'
        else:
            note = note + ', roughly ' + str(turns) + ' such hits to knock it out'
        if foesturdy:
            note = note + ', but Sturdy at full HP blocks a one hit knockout'
    elif isheal:
        missing = 1.0 - aprof['frac']
        if risk >= 0.95:
            val = 4.0
        elif missing < 0.25:
            val = 6.0
        else:
            val = 28.0 + 92.0 * min(0.5, missing) * (1.0 - min(1.0, risk))
        note = 'recovery, we sit at ' + pctstr(aprof['frac'], 1.0) + ' percent HP and the predicted incoming hit is ' + pctstr(risk, 3.0) + ' percent of current HP'
    elif isboost:
        if risk <= 0.3 and aprof['frac'] >= 0.6:
            val = 46.0
        elif risk <= 0.5 and aprof['frac'] >= 0.8:
            val = 30.0
        else:
            val = 5.0
        note = 'stat boost, predicted incoming hit is ' + pctstr(risk, 3.0) + ' percent of current HP'
    elif isstatus:
        if ctx['ostatus']:
            val = 3.0
        elif risk <= 0.7:
            val = 24.0 * acc
        else:
            val = 8.0
        note = 'status move on the target'
    else:
        val = 5.0
        note = 'no direct damage'
    val = val - 42.0 * pfaint
    head = name + ' (' + mtype + ' ' + (cat if cat else 'status') + ', ' + str(int(power)) + ' BP, ' + multstr(mult) + ', accuracy ' + pctstr(acc, 1.0) + ' percent'
    if prio > 0.0:
        head = head + ', priority ' + str(int(prio))
    return {'id': cid, 'kind': 'move', 'name': name, 'value': val, 'frac': frac, 'acc': acc,
            'prio': prio, 'komin': komin, 'koavg': koavg, 'is_switch': False,
            'is_heal': isheal, 'is_boost': (isboost or isstatus), 'unsafe': False,
            'hiddenpen': 10.0 * amatch['hidden'] * pfaint, 'brief': head + '): ' + note}


def switchcand(act, ctx, others, sandy, phase, aprof, amatch, streak):
    mon = act.get('pokemon') or {}
    cid = act.get('id')
    prof = ourprofile(mon, sandy, False)
    moves = mon.get('moves') or []
    mmu = matchup(ctx, prof, moves)
    name = str(mon.get('species') or act.get('label') or cid)
    entry = mmu['risk']
    fatal = mmu['exp'] >= 0.95
    covko = (mmu['cov'] >= 1.0) and (ctx['unknown'] > 0.0) and not mmu['sturdy']
    teamm = 0.0
    if others:
        tot = 0.0
        for oct2 in others:
            tot = tot + matchup(oct2, prof, moves)['margin']
        teamm = tot / float(len(others))
    if phase == 'switch':
        val = 52.0 * min(1.0, mmu['off']) + 30.0 * (1.0 - min(1.0, entry)) + 9.0 * clipv(mmu['margin'], -3.0, 3.0) + 6.0 * clipv(teamm, -2.0, 2.0)
        if mmu['faster']:
            val = val + 5.0
        if entry >= 1.0:
            val = val - 26.0
        if covko:
            val = val - 18.0 * ctx['unknown']
        if mmu['sturdy']:
            val = val + 8.0
        hpen = 14.0 * mmu['hidden']
        unsafe = False
    else:
        val = 46.0 * min(1.0, mmu['off']) + 26.0 * (1.0 - min(1.0, entry)) + 9.0 * clipv(mmu['margin'], -3.0, 3.0) + 4.0 * clipv(teamm, -2.0, 2.0) - 24.0
        if fatal:
            val = val - 40.0
        elif entry >= 0.75:
            val = val - 14.0
        if covko:
            val = val - 26.0 * ctx['unknown']
        if mmu['faster'] and mmu['off'] >= 0.9:
            val = val + 8.0
        val = val - 11.0 * min(2.0, streak)
        gained = 0.0
        for key in ['atk', 'spa', 'spe']:
            gained = gained + max(0.0, getnum(aprof['boosts'], key, 0.0))
        val = val - 9.0 * min(2.0, gained)
        if amatch['margin'] >= 1.0:
            val = val - 10.0
        hpen = 18.0 * mmu['hidden']
        if covko:
            hpen = hpen + 10.0
        unsafe = fatal
    brief = 'switch to ' + name + ' (' + pctstr(prof['frac'], 1.0) + ' percent HP, ' + '/'.join([str(tp) for tp in prof['types']]) + '): the hit it is predicted to take is about ' + pctstr(entry, 3.0) + ' percent of its HP'
    if fatal:
        brief = brief + ' and revealed or same type attacks already knock it out'
    elif covko:
        brief = brief + ' and an unrevealed ' + str(mmu['covtype']) + ' move could knock it out in one hit'
    if mmu['sturdy']:
        brief = brief + ' (Sturdy at full HP guarantees it survives one hit)'
    brief = brief + '; it then deals about ' + pctstr(mmu['off'], 4.0) + ' percent per turn with ' + str(mmu['offname']) + ', needing ' + str(mmu['turnsus']) + ' turns while the opponent needs ' + str(mmu['turnsthem'])
    if mmu['faster']:
        brief = brief + ', and it outspeeds'
    if phase != 'switch':
        brief = brief + '; switching concedes one free attack'
    return {'id': cid, 'kind': 'switch', 'name': name, 'value': val, 'frac': mmu['off'],
            'acc': 1.0, 'prio': 0.0, 'komin': False, 'koavg': False, 'is_switch': True,
            'is_heal': False, 'is_boost': False, 'unsafe': unsafe, 'hiddenpen': hpen,
            'brief': brief}


def instructions():
    return 'Choose the single action most likely to win the whole battle, not only this turn. Every option lists calculator estimates from public species data: type effectiveness, the share of the target remaining HP a hit removes, how many turns each side needs to knock the other out, and the damage a switch in is predicted to take. Damage numbers that mention an unrevealed move are speculation about coverage the opponent may or may not carry, so treat them as risk, not fact. Take a stated knockout when it is available, do not send a Pokemon into a hit that knocks it out on entry, keep a healthy answer for the opponent remaining team, prefer attacking when our active already wins the damage race, and remember that switching hands the opponent a free attack. Answer with exactly one of the listed action IDs.'


def build(obs, memory):
    chart = chartof()
    mem = memory if isinstance(memory, dict) else {}
    active = obs.get('active') or {}
    foe = obs.get('opponent_active') or {}
    field = obs.get('field') or {}
    sandy = norm(field.get('weather')) == 'sandstorm'
    phase = norm(obs.get('phase'))
    streak = getnum(mem, 'switch_streak', 0.0)
    ctx = oppctxof(chart, foe, sandy)
    aprof = ourprofile(active, sandy, True)
    legal = obs.get('legal_actions') or []
    amoves = []
    for act in legal:
        if isinstance(act, dict) and norm(act.get('kind')) == 'move' and isinstance(act.get('move'), dict):
            amoves.append(act['move'])
    amatch = matchup(ctx, aprof, amoves)
    others = []
    for fmn in obs.get('opponent_public_team') or []:
        if not isinstance(fmn, dict) or fmn.get('fainted') is True:
            continue
        if norm(fmn.get('species')) == norm(foe.get('species')):
            continue
        others.append(oppctxof(chart, fmn, sandy))
    cands = []
    for act in legal:
        if not isinstance(act, dict):
            continue
        cid = act.get('id')
        if not isinstance(cid, str):
            continue
        kind = norm(act.get('kind'))
        if kind == 'move':
            cands.append(movecand(act, ctx, aprof, amatch))
        elif kind == 'switch':
            cands.append(switchcand(act, ctx, others, sandy, phase, aprof, amatch, streak))
        else:
            lbl = str(act.get('label') or cid)
            cands.append({'id': cid, 'kind': kind, 'name': lbl, 'value': 4.0, 'frac': 0.0,
                          'acc': 1.0, 'prio': 0.0, 'komin': False, 'koavg': False,
                          'is_switch': False, 'is_heal': False, 'is_boost': False,
                          'unsafe': False, 'hiddenpen': 0.0, 'brief': lbl})
    finisher = None
    bestfin = -1.0
    for cnd in cands:
        if cnd['komin'] and cnd['acc'] >= 0.9:
            if amatch['faster'] or cnd['prio'] > 0.0 or amatch['risk'] < 0.85:
                score = cnd['acc'] * 100.0 + min(15.0, cnd['frac'] * 5.0)
                if cnd['prio'] > 0.0 and not amatch['faster']:
                    score = score + 15.0
                if score > bestfin:
                    bestfin = score
                    finisher = cnd['id']
    ranked = sorted(cands, key=lambda item: -item['value'])
    short = []
    for cnd in ranked:
        if len(short) >= 5:
            break
        if cnd['unsafe'] is True and len(ranked) > 1:
            continue
        if len(short) >= 2 and cnd['value'] < ranked[0]['value'] - 60.0:
            break
        short.append(cnd)
    havemove = False
    haveswitch = False
    for cnd in short:
        if cnd['is_switch']:
            haveswitch = True
        else:
            havemove = True
    for cnd in ranked:
        if len(short) >= 6:
            break
        if cnd['unsafe'] is True:
            continue
        if not havemove and not cnd['is_switch']:
            short.append(cnd)
            havemove = True
        elif not haveswitch and cnd['is_switch']:
            short.append(cnd)
            haveswitch = True
    if not short and cands:
        short = [cands[0]]
    criteria = {}
    for cnd in short:
        criteria[cnd['id']] = cnd['brief']
    if not criteria:
        criteria['none'] = 'no legal action is available'
    teamview = []
    for tmn in obs.get('own_team') or []:
        if not isinstance(tmn, dict):
            continue
        entry = {'species': tmn.get('species'), 'hp_percent': int(round(100.0 * getnum(tmn, 'hp_fraction', 1.0))),
                 'types': tmn.get('types'), 'status': tmn.get('status'),
                 'fainted': tmn.get('fainted') is True}
        if not entry['fainted']:
            tprof = ourprofile(tmn, sandy, False)
            tmu = matchup(ctx, tprof, tmn.get('moves') or [])
            entry['versus_current_foe'] = 'deals about ' + pctstr(tmu['off'], 3.0) + ' percent per turn, takes about ' + pctstr(tmu['risk'], 3.0) + ' percent per turn'
            notes = []
            for oct3 in others:
                omu = matchup(oct3, tprof, tmn.get('moves') or [])
                verdict = 'even'
                if omu['margin'] >= 0.5:
                    verdict = 'favourable'
                elif omu['margin'] <= -0.5:
                    verdict = 'unfavourable'
                notes.append(str(oct3['species']) + ': ' + verdict)
            entry['versus_other_foes'] = notes
        teamview.append(entry)
    foeview = []
    for fmn in obs.get('opponent_public_team') or []:
        if not isinstance(fmn, dict):
            continue
        names = []
        for mvx in fmn.get('revealed_moves') or []:
            if isinstance(mvx, dict):
                names.append(str(mvx.get('name')))
        foeview.append({'species': fmn.get('species'), 'types': fmn.get('types'),
                        'hp_percent': int(round(100.0 * getnum(fmn, 'hp_fraction', 1.0))),
                        'fainted': fmn.get('fainted') is True, 'revealed_moves': names})
    bench = []
    for cnd in cands:
        if cnd['is_switch']:
            bench.append(cnd['brief'])
    summary = {'turn': obs.get('turn'), 'phase': obs.get('phase'), 'weather': field.get('weather'),
               'our_active': {'species': active.get('species'),
                              'hp_percent': int(round(100.0 * aprof['frac'])),
                              'types': aprof['types'], 'status': active.get('status'),
                              'ability': active.get('ability'), 'item': active.get('item'),
                              'boosts': aprof['boosts']},
               'opponent_active': {'species': foe.get('species'),
                                   'hp_percent': int(round(100.0 * ctx['ofrac'])),
                                   'types': ctx['types'], 'status': foe.get('status'),
                                   'ability': foe.get('ability'), 'item': foe.get('item'),
                                   'revealed_move_count': len(ctx['orev']),
                                   'unrevealed_move_slots': max(0, 4 - len(ctx['orev']))},
               'race': {'moves_first': 'our active' if amatch['faster'] else 'the opponent active',
                        'our_best_damage_percent_per_turn': int(round(100.0 * min(3.0, amatch['off']))),
                        'our_best_move': amatch['offname'],
                        'turns_we_need_for_the_knockout': amatch['turnsus'],
                        'their_damage_from_known_moves_percent': int(round(100.0 * min(3.0, amatch['exp']))),
                        'their_risk_adjusted_damage_percent': int(round(100.0 * min(3.0, amatch['risk']))),
                        'turns_they_need_to_knock_us_out': amatch['turnsthem'],
                        'worst_unrevealed_coverage_type': amatch['covtype'],
                        'that_coverage_would_remove_percent': int(round(100.0 * min(3.0, amatch['cov'])))},
               'bench_options': bench,
               'caveat': 'All numbers are approximations from public species data. Opponent EVs, items, abilities and unrevealed moves stay unknown; coverage figures are hypothetical.'}
    return {'candidates': cands, 'shortlist': [cnd['id'] for cnd in short], 'finisher': finisher,
            'brief': [cnd['brief'] for cnd in cands], 'summary': summary,
            'teamview': teamview, 'foeview': foeview,
            'choice_questions': {'action': {'type': 'choice', 'instructions': instructions(), 'criteria': criteria}}}


def fallback(obs):
    cands = []
    criteria = {}
    for act in obs.get('legal_actions') or []:
        if not isinstance(act, dict):
            continue
        cid = act.get('id')
        if not isinstance(cid, str):
            continue
        mv = act.get('move') or {}
        lbl = str(act.get('label') or cid)
        val = getnum(mv, 'base_power', 0.0) * getnum(mv, 'type_multiplier', 1.0)
        cands.append({'id': cid, 'kind': norm(act.get('kind')), 'name': lbl, 'value': val,
                      'frac': 0.0, 'acc': 1.0, 'prio': 0.0, 'komin': False, 'koavg': False,
                      'is_switch': norm(act.get('kind')) == 'switch', 'is_heal': False,
                      'is_boost': False, 'unsafe': False, 'hiddenpen': 0.0, 'brief': lbl})
        criteria[cid] = lbl
    if not criteria:
        criteria['none'] = 'no legal action is available'
    return {'candidates': cands, 'shortlist': [cnd['id'] for cnd in cands[:5]], 'finisher': None,
            'brief': [cnd['brief'] for cnd in cands],
            'summary': {'note': 'detailed evaluation failed, simple fallback view',
                        'phase': obs.get('phase'), 'turn': obs.get('turn')},
            'teamview': [], 'foeview': [],
            'choice_questions': {'action': {'type': 'choice', 'instructions': instructions(), 'criteria': criteria}}}


def run(obs, nodes, memory):
    try:
        return build(obs, memory)
    except Exception:
        return fallback(obs)

def tofl(val, dflt):
    if val is None or isinstance(val, bool):
        return dflt
    if isinstance(val, (int, float)):
        return float(val)
    return dflt


def noulof(nodes, node, key, dflt):
    data = nodes.get(node)
    if not isinstance(data, dict):
        return dflt
    item = data.get(key)
    if not isinstance(item, dict):
        return dflt
    return tofl(item.get('noul'), dflt)


def choiceof(nodes, node, key):
    data = nodes.get(node)
    if not isinstance(data, dict):
        return None
    item = data.get(key)
    if not isinstance(item, dict):
        return None
    val = item.get('choice')
    if isinstance(val, str):
        return val
    return None


def firstlegal(obs):
    for act in obs.get('legal_actions') or []:
        if isinstance(act, dict) and isinstance(act.get('id'), str):
            return act['id']
    return ''


def decide(obs, nodes):
    feats = nodes.get('features') or {}
    cands = feats.get('candidates') or []
    byid = {}
    order = []
    for cnd in cands:
        if isinstance(cnd, dict) and isinstance(cnd.get('id'), str):
            byid[cnd['id']] = cnd
            order.append(cnd['id'])
    if not order:
        return firstlegal(obs)
    if len(order) == 1:
        return order[0]
    fin = feats.get('finisher')
    if isinstance(fin, str) and fin in byid:
        return fin
    swn = noulof(nodes, 'plan', 'switch_now', 0.5)
    rec = noulof(nodes, 'plan', 'recover_now', 0.5)
    setn = noulof(nodes, 'plan', 'setup_now', 0.5)
    hid = noulof(nodes, 'plan', 'hidden_coverage', 0.5)
    pool = []
    for cid in order:
        if byid[cid].get('unsafe') is not True:
            pool.append(cid)
    if not pool:
        pool = order
    scored = {}
    best = pool[0]
    bestval = -1000000.0
    for cid in pool:
        cnd = byid[cid]
        val = tofl(cnd.get('value'), 0.0)
        if cnd.get('is_switch') is True:
            val = val + 30.0 * (swn - 0.5)
        if cnd.get('is_heal') is True:
            val = val + 26.0 * (rec - 0.5)
        if cnd.get('is_boost') is True:
            val = val + 24.0 * (setn - 0.5)
        sig = 2.0 * hid - 1.0
        if sig < 0.0:
            sig = sig * 0.5
        val = val - tofl(cnd.get('hiddenpen'), 0.0) * sig
        scored[cid] = val
        if val > bestval:
            bestval = val
            best = cid
    pickid = choiceof(nodes, 'pick', 'action')
    if isinstance(pickid, str) and pickid in scored:
        if scored[pickid] >= bestval - 10.0:
            return pickid
    return best


def run(obs, nodes, memory):
    try:
        out = decide(obs, nodes)
    except Exception:
        out = firstlegal(obs)
    if not isinstance(out, str) or not out:
        return firstlegal(obs)
    return out
